ALTER TABLE "organizations" ADD COLUMN "description" character varying NULL, ADD COLUMN "classification" character varying NULL, ADD COLUMN "change_window" character varying NULL, ADD COLUMN "frozen" boolean NOT NULL DEFAULT false, ADD COLUMN "freeze_reason" character varying NULL, ADD COLUMN "cost_centre" character varying NULL, ADD COLUMN "ticket_key" character varying NULL, ADD COLUMN "cmdb_id" character varying NULL, ADD COLUMN "attested_by" character varying NULL, ADD COLUMN "attested_at" timestamptz NULL;
ALTER TABLE "teams" ADD COLUMN "description" character varying NULL, ADD COLUMN "attested_by" character varying NULL, ADD COLUMN "attested_at" timestamptz NULL;
CREATE TABLE "contacts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "role" character varying NOT NULL, "email" character varying NULL, "phone" character varying NULL, "url" character varying NULL, "notes" character varying NULL, "display_order" bigint NOT NULL DEFAULT 0, "organization_contacts" bigint NULL, "team_contacts" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "contacts_organizations_contacts" FOREIGN KEY ("organization_contacts") REFERENCES "organizations" ("id") ON DELETE CASCADE, CONSTRAINT "contacts_teams_contacts" FOREIGN KEY ("team_contacts") REFERENCES "teams" ("id") ON DELETE CASCADE);
CREATE INDEX "contact_role_display_order" ON "contacts" ("role", "display_order");
